// Slack sends three quite different things to this one address, and telling
// them apart is the whole job of this node.
//
//  1. A one-off 'url_verification' challenge, when the app is created.
//  2. A real message someone typed.
//  3. Noise: the agent's own replies, edits, joins, and anything without text.

const body = $json.body && typeof $json.body === 'object' && !Array.isArray($json.body)
  ? $json.body
  : {};

if (body.type === 'url_verification') {
  return [{ json: { kind: 'challenge', challenge: String(body.challenge ?? '') } }];
}

const event = body.event && typeof body.event === 'object' ? body.event : {};
const text = typeof event.text === 'string' ? event.text.trim() : '';

// A message with a bot_id is something a bot said, including this agent. Letting
// those through is how an agent ends up in a conversation with itself.
const fromABot = Boolean(event.bot_id) || event.subtype === 'bot_message';
const isMessage = event.type === 'message' || event.type === 'app_mention';

if (!isMessage || fromABot || text.length === 0) {
  return [{ json: { kind: 'ignore' } }];
}

// The agent requires real UUIDs, and it uses the session to remember a
// conversation. Deriving them by hand keeps one Slack thread on one session,
// so the agent follows a thread instead of meeting a stranger every message.
// Node's crypto is not available inside this sandbox, so this is a plain
// FNV-1a hash spread over the four rounds a UUID needs.
const uuidFrom = (seed) => {
  let hex = '';
  for (let round = 0; round < 4; round += 1) {
    let hash = 0x811c9dc5;
    const salted = `${round}:${seed}`;
    for (let index = 0; index < salted.length; index += 1) {
      hash ^= salted.charCodeAt(index);
      hash = Math.imul(hash, 0x01000193) >>> 0;
    }
    hex += hash.toString(16).padStart(8, '0');
  }
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    `4${hex.slice(13, 16)}`,
    `8${hex.slice(17, 20)}`,
    hex.slice(20, 32)
  ].join('-');
};

const channel = String(event.channel ?? 'unknown');
// Replies in a thread share the parent's timestamp, so a thread stays one
// conversation. A message in the channel is its own.
const thread = String(event.thread_ts ?? event.ts ?? '');
const teamId = String(body.team_id ?? '');

return [{
  json: {
    kind: 'message',
    sessionId: uuidFrom(`slack-session:${teamId}:${channel}:${thread}`),
    // Derived from the event id, so a Slack retry produces the same request id
    // rather than a second answer.
    requestId: uuidFrom(`slack-request:${String(body.event_id ?? event.ts ?? '')}`),
    message: text.slice(0, 8000),
    channel,
    threadTs: thread
  }
}];

// The agent answers in Markdown. Slack understands a dialect of its own, and
// the two differ in exactly one way that matters in practice: bold.
const reply = String($json.reply ?? $json.errorMessage ?? '').trim();

const text = reply.length === 0
  ? 'Your agent did not have an answer for that one.'
  : reply.replace(/\*\*(.+?)\*\*/g, '*$1*').slice(0, 3000);

return [{
  json: {
    channel: $('Read Slack Event').item.json.channel,
    thread_ts: $('Read Slack Event').item.json.threadTs,
    text
  }
}];
